DO $$ BEGIN IF (SELECT count(*) FROM public.commercial_lots WHERE block='P7' AND archived_at IS NULL AND status='AVAILABLE' AND official_area_sqm=7.5)<>57 THEN RAISE EXCEPTION 'P7_RELEASE_PRECONDITION_FAILED'; END IF; IF EXISTS(SELECT 1 FROM public.lot_prices p JOIN public.commercial_lots l ON l.id=p.lot_id WHERE l.block='P7' AND l.archived_at IS NULL AND p.pricing_mode<>'NOT_FOR_SALE') THEN RAISE EXCEPTION 'P7_PRICE_RECONCILIATION_REQUIRED'; END IF; UPDATE public.lot_prices p SET is_active=false WHERE p.lot_id IN(SELECT id FROM public.commercial_lots WHERE block='P7' AND archived_at IS NULL) AND p.pricing_mode='NOT_FOR_SALE' AND p.is_active=true; END $$;